  const M = () => MODELS[S.model];
  function lines() {
    const m = M(), L = [];
    const add = (id, qty, label) => { const it = ITEMS[id]; if (it && qty > 0) L.push({ it, qty: qty * 1, label: label || it.name }); };
    L.push({ it: { name: m.sku + " Barebone", price: m.base_price, lead: m.lead_weeks[0], watts: m.base_watts }, qty: 1, label: m.sku + " Base chassis (barebone)" });
    add(S.cpu, m.sockets);
    add(S.mem.id, S.mem.qty);
    add(S.boot, 1);
    add(S.drive.id, S.drive.qty);
    if (S.raid !== "raid-none") add(S.raid, 1);
    if (!m.gpu_fixed) add(S.gpu.id, S.gpu.qty);
    S.nic.forEach(n => add(n, 1));
    add(psuFor(), 1);
    if (S.cooling !== "cool-air") add(S.cooling, 1);
    add(S.warranty, 1);
    S.svc.forEach(s => add(s, 1));
    return L;
  }
  function watts() {
    const m = M();
    let w = m.base_watts;
    const W = (id, q) => (ITEMS[id]?.watts || 0) * q;
    w += W(S.cpu, m.sockets) + W(S.mem.id, S.mem.qty) + W(S.boot, 1) + W(S.drive.id, S.drive.qty);
    if (!m.gpu_fixed) w += W(S.gpu.id, S.gpu.qty);
    S.nic.forEach(n => w += W(n, 1));
    return Math.round(w);
  }
  function psuFor() {
    const need = watts() * C.meta.psu_headroom;
    const cand = (M().opts.psu || []).map(id => ITEMS[id]).sort((a, b) => a.capacity - b.capacity);
    return (cand.find(p => p.capacity >= need) || cand[cand.length - 1] || {}).id;
  }
  function totals() {
    const L = lines();
    const unit = L.reduce((s, l) => s + (l.it.price || 0) * l.qty, 0);
    const lead = Math.max(...L.map(l => l.it.lead || 0), M().lead_weeks[0]) + C.meta.assembly_weeks;
    return { L, unit, total: unit * S.units, lead: [lead, lead + C.meta.lead_buffer_weeks], w: watts() };
  }
  function validate() {
    const m = M(), out = [];
    const cpu = ITEMS[S.cpu], mem = ITEMS[S.mem.id], drv = ITEMS[S.drive.id], gpu = ITEMS[S.gpu.id];
    if (!cpu) out.push({ lv: "err", st: 1, msg: "Select a CPU." });
    if (!mem) out.push({ lv: "err", st: 2, msg: "Select memory." });
    else {
      const ch = m.mem_channels * m.sockets;
      if (S.mem.qty > m.dimm_slots) out.push({ lv: "err", st: 2, msg: `This model has up to ${m.dimm_slots} memory slots.` });
      if (S.mem.qty < m.sockets) out.push({ lv: "err", st: 2, msg: `A ${m.sockets}-CPU configuration needs at least ${m.sockets} DIMMs.` });
      else if (S.mem.qty % ch !== 0 && S.mem.qty < m.dimm_slots) out.push({ lv: "warn", st: 2, msg: `For maximum bandwidth, install DIMMs in multiples of ${ch} (${m.mem_channels} channels x ${m.sockets} CPUs).` });
    }
    if (drv) {
      const bays = m.bays[drv.form] || 0;
      if (!bays) out.push({ lv: "err", st: 3, msg: `This model has no ${drv.form} drive bays.` });
      else if (S.drive.qty > bays) out.push({ lv: "err", st: 3, msg: `Up to ${bays} ${drv.form} bays are available.` });
      if (drv.iface === "SAS" && S.raid === "raid-none") out.push({ lv: "err", st: 3, msg: "SAS drives require a RAID/HBA controller." });
    }
    if (gpu && !m.gpu_fixed) {
      if (S.gpu.qty > m.gpu_max) out.push({ lv: "err", st: 4, msg: `Up to ${m.gpu_max} GPUs are supported.` });
      if (gpu.dw && m.gpu_dw_max !== undefined && S.gpu.qty > m.gpu_dw_max) out.push({ lv: "err", st: 4, msg: `Up to ${m.gpu_dw_max} double-wide GPUs are supported.` });
    }
    const w = watts(), psu = ITEMS[psuFor()];
    if (psu && psu.capacity < w * C.meta.psu_headroom) out.push({ lv: "err", st: 6, msg: `PSU capacity is insufficient for the estimated ${won(w)} W. Please choose a lower GPU or CPU tier.` });
    const rackKw = (w * S.units) / 1000;
    if (m.needs_dlc && S.cooling === "cool-air") out.push({ lv: "err", st: 6, msg: "This model is liquid-cooled (DLC) only." });
    if (rackKw > C.meta.air_limit_kw_per_rack) out.push({ lv: "warn", st: 6, msg: `Installing ${S.units} unit${S.units > 1 ? "s" : ""} in one rack totals ${rackKw.toFixed(1)} kW, which may exceed the air-cooled rack limit (about ${C.meta.air_limit_kw_per_rack} kW per rack). Consider AIK DLC and CDU cooling design.` });
    return out;
  }
